"%% margin_04 : Robust stability margins of a cascaded (inner + outer) loop
%  INNER loop : G_in(s) = 1/(s*(s+4)), feedback gain ki = 9 (unity negative FB)
%               G_in_cl(s) = ki*G_in / (1 + ki*G_in)
%  OUTER loop : G_out(s) = 3/(s*(s+4))
%  Total open loop: L(s) = G_out(s) * G_in_cl(s)   (inner loop closed FIRST,
%  then cascaded). Compute gain/phase margins of L(s) and write result.json.

clear; clc;

s = tf('s');

% ---- Inner loop (closed first) ----
G_in = 1 / (s * (s + 4.0));
ki   = 9.0;
G_in_cl = feedback(ki * G_in, 1);        % unity negative feedback
% -> G_in_cl(s) = 9 / (s^2 + 4s + 9)

% ---- Outer loop ----
G_out = 3.0 / (s * (s + 4.0));

% ---- Cascaded total open loop ----
L = G_out * G_in_cl;
% -> L(s) = 27 / ( s*(s+4)*(s^2+4s+9) )

% ---- Stability margins of the total open loop ----
[Gm, Pm, Wcg, Wcp] = margin(L);
% Wcg = frequency where the GAIN margin is measured (phase crossover, phase = -180 deg)
% Wcp = frequency where the PHASE margin is measured (gain crossover, |L| = 0 dB)

gm_db  = 20 * log10(Gm);   % gain margin in dB
pm_deg = Pm;               % phase margin in degrees
w_gc   = Wcp;              % gain crossover frequency (rad/s)
w_pc   = Wcg;              % phase crossover frequency (rad/s)

% ---- Write result.json ----
result = struct('gm_db', gm_db, 'pm_deg', pm_deg, 'w_gc', w_gc, 'w_pc', w_pc);

fid = fopen('result.json', 'w');
if fid == -1
    error('margin_04: cannot open result.json for writing');
end
fwrite(fid, jsonencode(result), 'char');
fclose(fid);

fprintf('gm_db  = %.6f dB\n',   gm_db);
fprintf('pm_deg = %.6f deg\n',  pm_deg);
fprintf('w_gc   = %.6f rad/s\n', w_gc);
fprintf('w_pc   = %.6f rad/s\n', w_pc);"
